/** Bindings generated by `wrangler types`, with the vars widened and the non-committed ones added. */
export type Env = Omit<Cloudflare.Env, 'ENVIRONMENT' | 'ACCESS_TEAM_DOMAIN' | 'ACCESS_AUD'> & {
  ENVIRONMENT: string;
  ACCESS_TEAM_DOMAIN: string;
  ACCESS_AUD: string;
  /** Comma-separated. Set in the Cloudflare dashboard (or `.dev.vars`), never committed. */
  ALLOWED_EMAILS: string;
  /** Used only when `ENVIRONMENT === 'local'`. */
  DEV_USER_EMAIL?: string;
};

export type AppEnv = { Bindings: Env; Variables: { email: string } };
